function demoProg(rnd,title,topic){
  var lines=[];
  lines.push('// JAH demo program - run with: node demo.js');
  lines.push('// Demo: '+title);
  lines.push('(function(){"use strict";');
  lines.push('var topic='+jsq(topic)+';');
  var mode=(rnd()*3)|0, i;
  if(mode===0){
    lines.push('var steps=["charter","execute","verify","deliver"];');
    lines.push('console.log("Trace: "+topic);');
    lines.push('for(var i=0;i<steps.length;i++){console.log(" step "+(i+1)+": "+steps[i]+" ["+topic+"]");}');
    lines.push('console.log("OK - trace complete");');
  }else if(mode===1){
    lines.push('var vals=[],i;for(i=0;i<6;i++){vals.push((i*37+11)%97);}');
    lines.push('var sum=0;for(i=0;i<vals.length;i++){sum+=vals[i];}');
    lines.push('console.log("Data: "+topic+" -> ["+vals.join(", ")+"]");');
    lines.push('console.log("sum="+sum+" mean="+(sum/vals.length).toFixed(2));');
  }else{
    lines.push('var checks=[["inputs declared",true],["outputs verified",true],["deterministic",true]];');
    lines.push('var pass=0,i;for(i=0;i<checks.length;i++){console.log((checks[i][1]?"PASS ":"FAIL ")+checks[i][0]+" ["+topic+"]");if(checks[i][1]){pass++;}}');
    lines.push('console.log(pass+"/"+checks.length+" checks passed");');
  }
  lines.push('})();');
  return lines.join("\n");
}
